import 'package:flutter/material.dart';
import '../../../core/models/post.dart';
import '../../../services/social/community_memory_feed_service.dart';
class AurenCommunityMemoryScreen extends StatefulWidget {
 final String communityId; const AurenCommunityMemoryScreen({super.key,required this.communityId});
 @override State<AurenCommunityMemoryScreen> createState()=>_AurenCommunityMemoryScreenState();
}
class _AurenCommunityMemoryScreenState extends State<AurenCommunityMemoryScreen> {
 final _service=AurenCommunityMemoryFeedService();
 Future<void> _add() async {final title=TextEditingController(),body=TextEditingController();String kind='milestone';final ok=await showDialog<bool>(context:context,builder:(c)=>StatefulBuilder(builder:(c,setLocal)=>AlertDialog(title:const Text('إضافة إلى ذاكرة المجتمع'),content:SingleChildScrollView(child:Column(children:[DropdownButtonFormField<String>(initialValue:kind,items:const[DropdownMenuItem(value:'milestone',child:Text('إنجاز')),DropdownMenuItem(value:'decision',child:Text('قرار')),DropdownMenuItem(value:'outcome',child:Text('نتيجة'))],onChanged:(v){if(v!=null)setLocal(()=>kind=v);}),TextField(controller:title,maxLength:120,decoration:const InputDecoration(labelText:'العنوان')),TextField(controller:body,maxLength:2000,maxLines:4,decoration:const InputDecoration(labelText:'التفاصيل'))])),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('حفظ'))])));if(ok==true){try{await _service.create(communityId:widget.communityId,kind:kind,title:title.text,body:body.text);if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تمت الإضافة')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('تعذر الحفظ: $e')));}}title.dispose();body.dispose();}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Community Memory'),actions:[IconButton(onPressed:_add,icon:const Icon(Icons.add_circle_outline))]),body:StreamBuilder<List<AurenPost>>(stream:_service.watch(widget.communityId),builder:(c,s){if(s.hasError)return const Center(child:Text('تعذر تحميل الذاكرة. تحقق من عضويتك والاتصال.'));if(!s.hasData)return const Center(child:CircularProgressIndicator());if(s.data!.isEmpty)return const Center(child:Text('لا توجد إنجازات أو قرارات محفوظة بعد.'));return ListView.builder(padding:const EdgeInsets.all(16),itemCount:s.data!.length,itemBuilder:(c,i){final p=s.data![i];return Card(child:ListTile(leading:const Icon(Icons.history_edu_outlined),title:Text(p.contextLabel),subtitle:Text(p.text),isThreeLine:true));});}));
}
